package com.newzkl.platform.base.biz.order.model.req;import jakarta.validation.constraints.Size;import lombok.Data;import jakarta.validation.constraints.NotNull;import java.io.Serializable;/** * 售后操作记录-新增请求对象 * * @author sijiwang * @since 2026-01-23 */@Datapublic class RefundOperationRecordCreateReq implements Serializable {    private static final long serialVersionUID = 1L;    /**     * spu订单id     */    @NotNull(message = "SPU订单ID不能为空")    private Long spuOrderId;    /**     * 售后单refund表的主键     */    @NotNull(message = "售后单ID不能为空")    private Long refundId;    /**     * 操作人ID     */    @NotNull(message = "操作人ID不能为空")    private Long operatorId;    /**     * 操作方角色编码（对应RoleEnum.CompanyRole的code：1000=C端客户，1001=供应商，1002=渠道商，0=平台等）     */    @NotNull(message = "操作方角色编码不能为空")    private Long operatorRoleCode;    /**     * 操作方客户端类型（对应CommonEnum.Client的code：user=用户端，supplier=供应商端，channel=渠道商端，admin=平台端等）     */    @NotNull(message = "操作方客户端类型不能为空")    @Size(max = 32, message = "操作方客户端类型长度不能超过32位")    private String operatorClient;    /**     * 操作方名称     */    @NotNull(message = "操作方名称不能为空")    @Size(max = 64, message = "操作方名称长度不能超过64位")    private String operatorName;    /**     * 操作前售后单状态（对应RefundEnum.State的code）     */    @NotNull(message = "操作前售后单状态不能为空")    private Integer beforeState;    /**     * 操作后售后单状态（对应RefundEnum.State的code）     */    @NotNull(message = "操作后售后单状态不能为空")    private Integer afterState;    /**     * 操作类型（0=发起退款申请，1=审核通过，2=审核拒绝，3=提交物流信息，4=确认收货，5=退款完成，6=关闭售后，7=平台介入）     */    @NotNull(message = "操作类型不能为空")    private Integer operationType;    /**     * 操作内容描述     */    @Size(max = 512, message = "操作内容描述长度不能超过512位")    private String operationContent;    /**     * 本次操作涉及的退款金额     */    private Integer refundAmount;    /**     * 物流公司名称     */    @Size(max = 64, message = "物流公司名称长度不能超过64位")    private String freightCompanyName;    /**     * 物流单号     */    @Size(max = 64, message = "物流单号长度不能超过64位")    private String freightNo;    /**     * 操作原因/备注     */    @Size(max = 512, message = "操作原因长度不能超过512位")    private String reason;    /**     * 拓展字段（JSON格式）     */    @Size(max = 1024, message = "拓展字段长度不能超过1024位")    private String ext;}